                if (x) Y = 3'b001;
                else Y = 3'b000;
                z_reg = 1'b0;
            end
            3'b001: begin
                if (x) Y = 3'b100;
                else Y = 3'b001;
                z_reg = 1'b0;
            end
            3'b010: begin
                if (x) Y = 3'b001;
                else Y = 3'b010;
                z_reg = 1'b0;
            end
            3'b011: begin
                if (x) Y = 3'b010;
                else Y = 3'b001;
                z_reg = 1'b1;
            end
            3'b100: begin
                if (x) Y = 3'b100;
                else Y = 3'b011;
                z_reg = 1'b1;
            end
            default: begin
                Y = 3'b000;
                z_reg = 1'b0;
            end
        endcase
    end

    assign Y0 = Y[0];
    assign z = z_reg;

endmodule
